    rows.append({'record_id':item['record_id'],'repeat':item['repeat'],'result_path':item['result_path'],'result_sha256':sha(item['result_path']),'status':result['status'],'score':result['derived']['score'],'verdict':result['derived']['verdict'],'actual_issues':sorted(actual),'expected_verdict':req['verdict'],'required_issues':sorted(required),'detected_required':sorted(actual&required),'detected_forbidden':sorted(actual&forbidden),'verdict_match':None if req['verdict'] is None else result['derived']['verdict']==req['verdict'],'calls':len(result['raw_calls']),'response_ids':[c.get('response_id') for c in result['raw_calls']]})
